# region: emit
def emit(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs, cut=5):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: render
def render(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(sift(shape(emit(raw))))

